<div class="card form-card"><form enctype="multipart/form-data" method="post" action="<?= $link($organization?'/organizations/'.$organization['id'].'/save':'/organizations/save') ?>"><?= $csrf ?><label>Organization name<input name="name" value="<?= $e($organization['name']??'') ?>" maxlength="190" required></label><label>Description<textarea name="description" rows="4"><?= $e($organization['description']??'') ?></textarea></label><label>Website<input name="website" type="url" value="<?= $e($organization['website']??'') ?>" maxlength="2048" placeholder="https://example.com"></label><label>Phone<input name="phone" value="<?= $e($organization['phone']??'') ?>" maxlength="100"></label><label>Address<textarea name="address" maxlength="2000"><?= $e($organization['address']??'') ?></textarea></label><label>Organization notes<textarea name="notes" maxlength="10000"><?= $e($organization['notes']??'') ?></textarea></label><label>Logo<input name="logo" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="help">PNG, JPEG or WebP; maximum 1 MiB and 4096 pixels.</p><?php if(!empty($organization['logo_mime'])): ?><img class="org-logo" src="<?= $link('/organizations/'.$organization['id'].'/logo') ?>" alt="Current logo"><label class="checkbox"><input type="checkbox" name="remove_logo" value="1">Remove current logo</label><?php endif; ?><div class="form-actions"><button class="button">Save organization</button><a class="button secondary" href="<?= $link('/organizations') ?>">Cancel</a></div></form></div>
